```

**Role seeding + DB migration + API endpoints** — Add BEFORE `app.Run();`:
```csharp
// Seed roles and apply migrations
using (var scope = app.Services.CreateScope())
{
    var dbContext = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
    dbContext.Database.Migrate();

    var roleManager = scope.ServiceProvider.GetService<RoleManager<IdentityRole>>();
    if (roleManager is not null)
    {
        foreach (var role in new[] { "Dispatcher", "Customer" })
        {
            if (!await roleManager.RoleExistsAsync(role))
                await roleManager.CreateAsync(new IdentityRole(role));
        }
    }
}

// Shipment API endpoints
var api = app.MapGroup("api/shipments");

api.MapGet("", async (IShipmentService service) =>
    Results.Ok(await service.GetAllShipmentsAsync()))
    .RequireAuthorization(policy => policy.RequireRole("Dispatcher"));

api.MapGet("track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
{
    var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
    return shipment is null ? Results.NotFound() : Results.Ok(shipment);
}).RequireAuthorization();

api.MapGet("my", async (HttpContext context, ApplicationDbContext db) =>
{
    var userId = context.User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value;
    if (userId is null) return Results.Unauthorized();
    var shipments = await db.Shipments
        .Where(s => s.CustomerUserId == userId)
        .Select(s => new ShipmentDto
        {
            Id = s.Id,
            TrackingNumber = s.TrackingNumber,
            Origin = s.Origin,
            Destination = s.Destination,
            Status = s.Status,
            CreatedDate = s.CreatedDate,
            EstimatedDelivery = s.EstimatedDelivery,
            ActualDelivery = s.ActualDelivery,
            RecipientName = s.RecipientName,
            RecipientEmail = s.RecipientEmail,
            Description = s.Description,
            CustomerUserId = s.CustomerUserId
        })
        .ToListAsync();
    return Results.Ok(shipments);
}).RequireAuthorization();

api.MapPost("", async (ShipmentDto dto, IShipmentService service) =>
    Results.Created($"api/shipments/track/{(await service.CreateShipmentAsync(dto)).TrackingNumber}",
        await service.GetShipmentByTrackingNumberAsync((await service.CreateShipmentAsync(dto)).TrackingNumber)))
    .RequireAuthorization(policy => policy.RequireRole("Dispatcher"));

api.MapPut("{id}/status", async (int id, ShipmentStatus status, IShipmentService service) =>
